                (
                    unsafe H.loadWidening(from: source),
                    unsafe H.Vector(raw: HighwayReference.loadWideningI16ToI32(source))
                )
            }.result
            mismatches.check(portResult, referenceResult, "from: \(describe(from))")
        }
        mismatches.record()
    }

